import {randomUUID} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {OrdinaryRestoreHost} from '../../host/ordinary-restore.mjs';
import {restorePathHash} from '../../host/ordinary-restore-private.mjs';
import {MaintenanceIO} from '../../host/maintenance-io.mjs';
import {tablet,defer} from './conversation-management.mjs';
export {tablet,defer};
const vectors=JSON.parse(readFileSync(new URL('./ordinary-restore-reference-vectors.json',import.meta.url)));
export const source=vectors.context.source;
export const identity={connection_id:tablet.connection_id,boot_id:tablet.boot_id};
export const preview=vectors.context.preview;
export function makeIntent(operation,path){return {...structuredClone(vectors.context.intent),operation,source_path_sha256:restorePathHash('source',path),target_generation:randomUUID()};}
export function restoreReport(selector,body,state){const r={report_version:1,operation:selector,status:'ok',outcome:selector==='prepare'?'prepared':selector==='apply'?state.apply:state.status,disk_readback_verified:false,runtime_activation:'unverified',data:null};if(selector==='prepare')r.data={preview:structuredClone(preview),intent:makeIntent(body.operation,body.source)};else if(['restored','desired-generation-observed'].includes(r.outcome)){r.disk_readback_verified=selector==='apply';r.data={inspection:structuredClone(preview.target),configuration_applied:false};}else if(['unknown','not-activated'].includes(r.outcome))r.status='failed';return r;}
export function restoreFixture(options={}){const io=new MaintenanceIO(),calls=[],state={hooks:0,apply:'unknown',status:'unresolved',onRaw:null};const observer={lastObservation:structuredClone(tablet),cancels:0,cancel(){this.cancels++;},async run(action,q){if(action!=='ordinary-restore')throw Error('Unexpected synthetic action');const body=JSON.parse(Buffer.from(q.input_base64,'base64'));calls.push({action,selector:q.selector,body:structuredClone(body),input:q.input_base64,budget:q.budget_ms});let r=restoreReport(q.selector,body,state);if(state.onRaw)r=await state.onRaw(r,q,body);return {contract_version:1,status:'observed',observation:structuredClone(this.lastObservation),ordinary_restore_raw:{status:'reported',stdout_base64:Buffer.from(typeof r==='string'?r:JSON.stringify(r)+'\n').toString('base64')}};}};
 const host=new OrdinaryRestoreHost({observer,io,beforeIO:()=>{state.hooks++;},...options});const use=(action,reference,invocation=randomUUID(),sample=observer.lastObservation)=>host.request({action,connection_id:sample.connection_id,boot_id:sample.boot_id,reference,invocation});const prepare=(path=source,invocation=randomUUID())=>host.request({action:'prepare',connection_id:observer.lastObservation.connection_id,boot_id:observer.lastObservation.boot_id,invocation,source:path});return {io,host,calls,state,observer,use,prepare};}
export function addRestoreFixture(f,options={}){const local=restoreFixture(),previous=f.observer.run;f.observer.run=async function(action,q){if(action==='ordinary-restore'){local.observer.lastObservation=this.lastObservation;const r=await local.observer.run(action,q);f.calls.push(...local.calls.splice(0));return r;}return previous.call(this,action,q);};const restore=new OrdinaryRestoreHost({observer:f.observer,io:f.io,...options}),lanes={...f.lanes,restore};for(const [name,h]of Object.entries(lanes))h.beforeIO=()=>{local.state.hooks++;for(const [other,peer]of Object.entries(lanes))if(other!==name)peer.invalidate();};return {...f,restore,restoreState:local.state,lanes};}
